function genreIndex(genre){let genres=[...new Set(books.map(b=>String(b.genre||"").trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,undefined,{sensitivity:"base"}));return Math.max(0,genres.indexOf(String(genre||"")))}
