function normalizeFormat(format){let raw=String(format??"").replace(/[\u00a0\u2007\u202f]/g," ").replace(/&amp;/gi,"&").trim();if(!raw)return "";let low=raw.toLowerCase().normalize("NFKC").replace(/[‐-―−]/g,"-").replace(/[&+/,|]/g," and ").replace(/\s+/g," ").trim();if(low==="wishlist")return "Wishlist";if(low==="book & kindle"||low==="book and kindle"||low==="physical and kindle"||low==="kindle and physical"||low==="both")return "Book & Kindle";if(low==="book"||low==="physical"||low==="print"||low==="paperback"||low==="hardcover"||low==="hardback"||low==="paper")return "Physical";if(low==="kindle"||low==="ebook"||low==="e-book"||low==="digital")return "Kindle";let hasKindle=/\bkindle\b|\be-?book\b|\bebook\b|\bdigital\b/.test(low);let hasPhysical=/\bphysical\b|\bbook\b|\bprint\b|\bpaperback\b|\bhardcover\b|\bhardback\b|\bpaper\b/.test(low);if(hasKindle&&hasPhysical)return "Book & Kindle";if(hasKindle)return "Kindle";if(hasPhysical)return "Physical";return raw}
