function coverUrlFor(b){if(b.coverUrl)return b.coverUrl;if(b.coverId)return `https://covers.openlibrary.org/b/id/${encodeURIComponent(b.coverId)}-M.jpg`;if(b.isbn)return `https://covers.openlibrary.org/isbn/${encodeURIComponent(String(b.isbn).replace(/[^0-9Xx]/g,""))}-M.jpg`;return ""}
