function renderDetailsCoverBox(b){let u=coverUrlFor(b);let ufb=coverFallbackUrl(b);let ufbAttr=(u&&ufb&&ufb!==u)?` data-fallback="${esc(ufb)}"`:"";let inner=u?`<img src="${esc(u)}" alt="" data-cover-url="${esc(u)}"${ufbAttr} onerror="handleCoverImgError(this)">`:`<span class="cover-placeholder">${esc((b.title||"?")[0])}</span>`;$("detailsCover").innerHTML=inner+'<button type="button" class="cover-edit-btn" title="Change cover" aria-label="Change cover">✏️</button>'}
