function card(b,w=false){let cu=coverUrlFor(b);let fb=coverFallbackUrl(b);let fbAttr=(cu&&fb&&fb!==cu)?` data-fallback="${esc(fb)}"`:"";let cover=cu?`<img src="${esc(cu)}" alt="" loading="lazy" data-cover-url="${esc(cu)}"${fbAttr} onerror="handleCoverImgError(this)">`:`<span class="cover-placeholder">${esc((b.title||"?")[0])}</span>`;let gs=genreStyle(b.genre);let action=w?`<button class="btn" onclick="event.stopPropagation();buy('${esc(b.id)}')">Bought</button>`:"";return `<div class="card book-card" data-book-id="${esc(b.id)}"><div class="book"><div class="cover">${cover}</div><div style="min-width:0;flex:1"><h3>${esc(b.title)}</h3><div class="meta">${esc(b.author||"Unknown author")}${b.series&&String(b.series).trim().toLowerCase()!=="no"?` · ${esc(b.series)}${b.seriesNo&&String(b.seriesNo).toLowerCase()!=="standalone"?` #${esc(b.seriesNo)}`:""}`:""}</div><div class="tags">${b.genre?`<span class="tag genre-tag" style="${gs}">${esc(b.genre)}</span>`:""}${formatTagsHtml(b.format)}${b.readingStatus?`<span class="tag ${readingStatusClass(b.readingStatus)}">${esc(b.readingStatus)}</span>`:""}</div></div>${action?`<div class="actions cover-action">${action}</div>`:""}</div></div>`}
function authorNamePart(name,part){name=String(name||"").trim();if(!name)return "";let parts=name.split(/\s+/).filter(Boolean);if(!parts.length)return "";return part==="first"?parts[0]:parts[parts.length-1]}
function sortBooks(arr,key){let [field,dir]=key.split("-"),out=[...arr];out.sort((a,b)=>{if(field==="series"){let as=String(a.series||"").toLocaleLowerCase(),bs=String(b.series||"").toLocaleLowerCase();let n=as.localeCompare(bs,undefined,{numeric:true,sensitivity:"base"});if(n===0){let an=parseFloat(String(a.seriesNo||"").replace(/[^0-9.]+/g,""));let bn=parseFloat(String(b.seriesNo||"").replace(/[^0-9.]+/g,""));if(Number.isNaN(an))an=Infinity;if(Number.isNaN(bn))bn=Infinity;n=an-bn;if(n===0)n=String(a.title||"").localeCompare(String(b.title||""),undefined,{numeric:true,sensitivity:"base"})}return dir==="desc"?-n:n}let av,bv;if(field==="authorFirst"||field==="authorSurname"){let part=field==="authorFirst"?"first":"last";av=authorNamePart(a.author,part).toLocaleLowerCase();bv=authorNamePart(b.author,part).toLocaleLowerCase()}else{let k=field==="title"?"title":field;av=String(a[k]||"").toLocaleLowerCase();bv=String(b[k]||"").toLocaleLowerCase()}if(!av&&!bv)return 0;if(!av)return 1;if(!bv)return -1;let n=av.localeCompare(bv,undefined,{numeric:true,sensitivity:"base"});return dir==="desc"?-n:n});return out}
function renderLibrary(){let q=$("search").value.toLowerCase(),a0=$("author").value,g=$("genre").value,s=$("series").value,rs=$("readState").value,key=$("librarySort").value,a=owned().filter(b=>(!q||(b.title+" "+b.author).toLowerCase().includes(q))&&(!a0||b.author===a0)&&(!g||b.genre===g)&&(!s||b.series===s)&&(rs!=="all"||normalizedReadingStatus(b.readingStatus)===rs));a=sortBooks(a,key);$("libSummary").textContent=`Showing ${a.length} of ${owned().length} owned books`;$('libraryList').innerHTML=a.length?a.map(b=>card(b)).join(""):'<div class="empty">No matching books.</div>'}
