function renderWishlist(){let q=$("wishSearch").value.toLowerCase(),a0=$("wishAuthor").value,g=$("wishGenre").value,s=$("wishSeries").value,all=wish(),a=all.filter(b=>(!q||(b.title+" "+b.author).toLowerCase().includes(q))&&(!a0||b.author===a0)&&(!g||b.genre===g)&&(!s||b.series===s));a=sortBooks(a,$("wishlistSort").value);$("wishSummary").textContent=`Showing ${a.length} of ${all.length} books on your wishlist`;$("wishlistList").innerHTML=a.length?a.map(b=>card(b,true)).join(""):(all.length?'<div class="empty">No matching books.</div>':'<div class="empty">Your wishlist is empty.<br>Scan an ISBN to add a book.</div>')}
function mergeFormatValues(a,b){let fa=normalizeFormat(a),fb=normalizeFormat(b);if(fa==="Wishlist"||fb==="Wishlist")return "Wishlist";let physical=formatHas({format:fa},"Physical")||formatHas({format:fb},"Physical"),kindle=formatHas({format:fa},"Kindle")||formatHas({format:fb},"Kindle");return physical&&kindle?"Book & Kindle":physical?"Physical":kindle?"Kindle":fa||fb||""}
