function formatHas(b,format){let f=normalizeFormat(b.format),raw=String(b.format??"").trim().toLowerCase().replace(/\s+/g," ");if(format==="Wishlist")return f==="Wishlist";if(format==="Physical")return f==="Physical"||f==="Book & Kindle";if(format==="Kindle")return f==="Kindle"||f==="Book & Kindle";if(format==="Both")return f==="Book & Kindle"||raw==="both"||raw==="book & kindle"||raw==="book and kindle"||raw==="physical and kindle"||raw==="kindle and physical";return false}
