function formatKind(value){const raw=String(value??"").replace(/[\u00a0\u2007\u202f]/g," ").replace(/&amp;/gi,"&").trim();if(!raw)return "";const low=raw.toLowerCase().normalize("NFKC").replace(/[‐-―−]/g,"-").replace(/\s+/g," ").trim();const compact=low.replace(/[&+/,|]/g," and ").replace(/\s+/g," ").trim();if(compact==="book and kindle"||compact==="physical and kindle"||compact==="kindle and physical"||compact==="both")return "Both";if(compact==="kindle"||compact==="ebook"||compact==="e-book"||compact==="digital")return "Kindle";if(compact==="book"||compact==="physical"||compact==="print"||compact==="paperback"||compact==="hardcover"||compact==="hardback"||compact==="paper")return "Physical";const hasK=/\bkindle\b|\be-?book\b|\bebook\b|\bdigital\b/.test(compact),hasP=/\bphysical\b|\bbook\b|\bprint\b|\bpaperback\b|\bhardcover\b|\bhardback\b|\bpaper\b/.test(compact);return hasK&&hasP?"Both":hasK?"Kindle":hasP?"Physical":""}
