function stats(){let o=owned(),w=wish(),m={};o.forEach(b=>{let normalized=normalizeFormat(b.format);if(b.format!==normalized)b.format=normalized});localStorage.setItem(STORAGE,JSON.stringify(books));$("total").textContent=o.length;$("wish").textContent=w.length;let physicalCount=o.filter(b=>formatHas(b,"Physical")).length,kindleCount=o.filter(b=>formatHas(b,"Kindle")).length;$("physical").textContent=physicalCount;$("kindle").textContent=kindleCount;o.forEach(b=>{let g=String(b.genre||"").trim();if(g)m[g]=(m[g]||0)+1});let genres=Object.keys(m);let genreColours=genres.map(g=>{let i=genreIndex(g);return `hsl(${Math.round((i*137.508)%360)} 72% 55%)`});chart("genresChart","doughnut",genres,Object.values(m),genreColours);let bothCount=o.filter(isBothFormat).length;let physicalOnlyCount=o.filter(b=>!isBothFormat(b)&&formatKind(b.format)==="Physical").length;let kindleOnlyCount=o.filter(b=>!isBothFormat(b)&&formatKind(b.format)==="Kindle").length;chart("formatsChart","doughnut",[`Physical (${physicalOnlyCount})`,`Kindle (${kindleOnlyCount})`,`Both (${bothCount})`],[physicalOnlyCount,kindleOnlyCount,bothCount]);let boughtCount=Object.keys(boughtHistory).length;chart("conversionChart","bar",["Wishlist","Bought"],[w.length,boughtCount]);}
