function addScannedBook(meta,format,bought,allowDuplicate=false){let incoming={title:meta.title,author:meta.author,genre:meta.genre||"Unknown",series:meta.series||"",seriesNo:meta.seriesNo||"",isbn:meta.isbn,coverUrl:meta.coverUrl,coverId:meta.coverId};let existing=allowDuplicate?null:books.find(x=>x.format!=="Wishlist"&&sameBook(x,incoming));if(bought&&existing){mergeOwnedFormat(existing,format);existing.coverUrl=existing.coverUrl||incoming.coverUrl;existing.coverId=existing.coverId||incoming.coverId;existing.readingStatus=existing.readingStatus||"Unread";persist();toast("Updated your library format");return}let wishExisting=allowDuplicate?null:books.find(x=>x.format==="Wishlist"&&sameBook(x,incoming));if(bought&&wishExisting){wishExisting.format=format;wishExisting.boughtAt=new Date().toISOString();boughtHistory[wishExisting.id]={boughtAt:wishExisting.boughtAt,format,title:wishExisting.title};localStorage.setItem(BOUGHT_STORAGE,JSON.stringify(boughtHistory));persist();toast("Moved to your library");return}let book={id:crypto.randomUUID(),...incoming,format,addedAt:new Date().toISOString(),readingStatus:"Unread"};if(bought){book.boughtAt=new Date().toISOString();boughtHistory[book.id]={boughtAt:book.boughtAt,format,title:book.title};localStorage.setItem(BOUGHT_STORAGE,JSON.stringify(boughtHistory))}books.push(book);persist();$("scanStatus").textContent=(bought?"Added to your library: ":"Added to Wishlist: ")+book.title;toast(bought?"Added to your library":"Added to Wishlist")}
