function openManualEntry(prefillIsbn,prefill){prefill=prefill||{};populateGenreOptions(prefill.genre||"");$("meTitle").value=prefill.title||"";$("meAuthor").value=prefill.author||"";$("meSeries").value=prefill.series||"";$("meSeriesNo").value=prefill.seriesNo||"";$("meFormat").value="Physical";$("meStatus").value="bought";$("newGenreWrap").style.display="none";$("newGenre").value="";manualEntryIsbn=prefillIsbn||"";manualEntryCoverUrl=prefill.coverUrl||"";manualEntryCoverId=prefill.coverId||"";if(manualEntryIsbn){$("meIsbnNote").textContent="ISBN: "+manualEntryIsbn;$("meIsbnNote").style.display=""}else $("meIsbnNote").style.display="none";$("manualEntryDialog").showModal();$("meTitle").focus()}
