$("meSeries").addEventListener("input",e=>{if(e.target.value.trim().toLowerCase()==="no")$("meSeriesNo").value="Standalone";else if($("meSeriesNo").value.trim().toLowerCase()==="standalone")$("meSeriesNo").value=""});
$("meSave").onclick=()=>{let title=$("meTitle").value.trim();if(!title){toast("Title is required");return}let isbn=(manualEntryIsbn||"").replace(/[^0-9Xx]/g,"");let genre=$("meGenre").value==="__other__"?$("newGenre").value.trim():$("meGenre").value.trim();if(!genre){toast("Please select or add a genre");return}let series=$("meSeries").value.trim(),seriesNo=$("meSeriesNo").value.trim();if(series.toLowerCase()==="no")seriesNo="Standalone";let meta={title,author:$("meAuthor").value.trim()||"Unknown author",genre,series,seriesNo,isbn,coverUrl:manualEntryCoverUrl||"",coverId:manualEntryCoverId||""};let st=$("meStatus").value,format=st==="wishlist"?"Wishlist":$("meFormat").value;let existing=findDuplicate(title,meta.author,format);if(existing){$("manualEntryDialog").close();showDuplicateWarning(existing,meta,format,()=>addScannedBook(meta,format,st==="bought"));return}addScannedBook(meta,format,st==="bought");$("manualEntryDialog").close()};
function showScanResult(existing,meta){$("scanResultTitle").textContent=meta.title||"Unknown title";$("scanResultAuthor").textContent=meta.author||"Unknown author";$("scanResultStatus").textContent=existing?(existing.format==="Wishlist"?"This book is already on your wishlist.":"This book is already in your library."):"Not yet in your library or wishlist.";$("scanResultFormatRow").style.display="";let actions=$("scanResultActions");actions.innerHTML=existing&&existing.format==="Wishlist"?'<button class="btn secondary" id="scanResultClose">Cancel</button><button class="btn" id="scanResultMarkBought">Mark as bought</button>':'<button class="btn secondary" id="scanResultWishlistBtn">Add to Wishlist</button><button class="btn" id="scanResultBoughtBtn">Mark as bought</button>';if(existing&&existing.format==="Wishlist"){$("scanResultClose").onclick=()=>$("scanResultDialog").close();$("scanResultMarkBought").onclick=()=>{let f=$("scanResultFormat").value;existing.format=f;existing.boughtAt=new Date().toISOString();boughtHistory[existing.id]={boughtAt:existing.boughtAt,format:f,title:existing.title||""};localStorage.setItem(BOUGHT_STORAGE,JSON.stringify(boughtHistory));persist();$("scanResultDialog").close();toast("Moved to your library")}}else{$("scanResultWishlistBtn").onclick=()=>{let f="Wishlist",dup=findDuplicate(meta.title,meta.author,f);if(dup){$("scanResultDialog").close();showDuplicateWarning(dup,meta,f,()=>addScannedBook(meta,f,false,true));return}addScannedBook(meta,f,false);$("scanResultDialog").close()};$("scanResultBoughtBtn").onclick=()=>{let f=$("scanResultFormat").value,dup=findDuplicate(meta.title,meta.author,f);if(dup){$("scanResultDialog").close();showDuplicateWarning(dup,meta,f,()=>addScannedBook(meta,f,true,true));return}addScannedBook(meta,f,true);$("scanResultDialog").close()}}$("scanResultDialog").showModal()}
async function startCamera(){if(!navigator.mediaDevices?.getUserMedia){$("scanStatus").textContent="Camera is not supported here.";return}try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:"environment"}},audio:false});$("video").srcObject=stream;if("BarcodeDetector"in window){let d=new BarcodeDetector({formats:["ean_13","ean_8","upc_a","upc_e"]});let loop=async()=>{if(!$("scanner").classList.contains("active"))return;try{let c=await d.detect($("video"));if(c.length){await lookupISBN(c[0].rawValue);return}}catch{}frame=requestAnimationFrame(loop)};loop()}else $("scanStatus").textContent="Camera active. Automatic barcode detection isn't supported by this browser; enter the ISBN manually."}catch{$("scanStatus").textContent="Camera permission unavailable. Enter the ISBN manually."}}function stopCamera(){if(frame)cancelAnimationFrame(frame);if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}}

function normTitle(s){return String(s||"").toLowerCase().replace(/[’']/g,"").replace(/[^a-z0-9]+/g," ").replace(/\b(a|an|the)\b/g," ").replace(/\s+/g," ").trim()}
function authorTokens(s){return String(s||"").toLowerCase().replace(/[^a-z0-9]+/g," ").split(/\s+/).filter(x=>x.length>2)}
async function getCoverFromOpenLibrary(b){try{if(b.isbn){let isbn=String(b.isbn).replace(/[^0-9Xx]/g,"");let r=await fetch(`https://openlibrary.org/api/books?bibkeys=ISBN:${encodeURIComponent(isbn)}&jscmd=data&format=json`),d=await r.json(),x=d[`ISBN:${isbn}`],u=x?.cover?.medium||x?.cover?.large||x?.cover?.small;if(u)return{url:u,source:"Open Library"}}let q=encodeURIComponent(`${b.title||""} ${b.author||""}`.trim()),r=await fetch(`https://openlibrary.org/search.json?q=${q}&limit=10`),d=await r.json(),docs=d.docs||[],bt=normTitle(b.title),at=authorTokens(b.author),scored=docs.filter(x=>x.cover_i).map(x=>{let t=normTitle(x.title),names=(x.author_name||[]).join(" ").toLowerCase(),score=(t===bt?100:0)+(t.includes(bt)||bt.includes(t)?25:0)+at.filter(a=>names.includes(a)).length*10;return{x,score}}).sort((a,b)=>b.score-a.score);if(scored[0]&&scored[0].score>=100)return{url:`https://covers.openlibrary.org/b/id/${scored[0].x.cover_i}-M.jpg`,coverId:scored[0].x.cover_i,source:"Open Library"}}catch(e){}return null}
async function getCoverFromGoogleBooks(b){try{let q=b.isbn?`isbn:${String(b.isbn).replace(/[^0-9Xx]/g,"")}`:`intitle:${b.title||""}+inauthor:${b.author||""}`,r=await fetch(`https://www.googleapis.com/books/v1/volumes?q=${encodeURIComponent(q)}&maxResults=10`),d=await r.json(),items=d.items||[],bt=normTitle(b.title),at=authorTokens(b.author),scored=items.filter(x=>x.volumeInfo?.imageLinks).map(x=>{let v=x.volumeInfo,t=normTitle(v.title),names=(v.authors||[]).join(" ").toLowerCase(),score=(t===bt?100:0)+(t.includes(bt)||bt.includes(t)?25:0)+at.filter(a=>names.includes(a)).length*10;return{x,score}}).sort((a,b)=>b.score-a.score),v=scored[0]?.x?.volumeInfo,u=v?.imageLinks?.thumbnail||v?.imageLinks?.smallThumbnail;if(u)return{url:u.replace(/^http:/,"https:"),source:"Google Books"}}catch(e){}return null}
const COVER_DB="mpl-cover-cache-v2";const coverMemory=new Map();
function openCoverDB(){return new Promise((resolve,reject)=>{try{let r=indexedDB.open(COVER_DB,1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains("covers"))r.result.createObjectStore("covers")};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)}catch(e){reject(e)}})}
