async function hydrateCoverImages(){let imgs=[...document.querySelectorAll("img[data-cover-url]")];for(let i=0;i<imgs.length;i+=8){await Promise.all(imgs.slice(i,i+8).map(async img=>{let url=img.dataset.coverUrl;if(!url)return;let local=await cachedCoverUrl(url);if(!local)local=await cacheCover(url);if(local)img.src=local}))}}
async function autoAddCovers(showProgress=false){let targets=books.filter(b=>!b.coverUrl&&!b.coverId);let total=targets.length;if(showProgress&&total)$("coverProgress").textContent=`Finding covers for ${total} book${total===1?"":"s"}…`;let changed=0;for(let i=0;i<targets.length;i++){let b=targets[i],found=null;try{found=await getCoverFromOpenLibrary(b);if(!found)found=await getCoverFromGoogleBooks(b)}catch(e){}if(found){b.coverUrl=found.url;if(found.coverId)b.coverId=found.coverId;b.coverSource=found.source||"";await cacheCover(found.url);changed++;localStorage.setItem(STORAGE,JSON.stringify(books));renderAll();await hydrateCoverImages()}if(showProgress&&total)$("coverProgress").textContent=`Finding covers… ${i+1} of ${total} · ${changed} found`}if(showProgress)$("coverProgress").textContent=total?(changed?`Found ${changed} new cover${changed===1?"":"s"}. Existing covers were not searched again.`:"No new covers found. Existing covers were not searched again."):"All books already have covers. Nothing was searched again."}
