function sanitizeSynopsis(text){if(!text)return text;let t=String(text);t=t.replace(/<[^>]+>/g," ");t=t.replace(/&nbsp;/gi," ").replace(/&amp;/gi,"&").replace(/&quot;/gi,'"').replace(/&#3?9;/gi,"'").replace(/&lt;/gi,"<").replace(/&gt;/gi,">");let cutMarkers=[/From Publishers Weekly/i,/From Library Journal/i,/From School Library Journal/i,/From Booklist/i,/From Kirkus Reviews/i,/From the Publisher/i,/Product Description/i,/Editorial Reviews?/i,/About the Author/i,/Praise for/i];for(const m of cutMarkers){let idx=t.search(m);if(idx>15)t=t.slice(0,idx)}t=t.replace(/\s+/g," ").trim();return t}
