async function lintGrammar(text){if(!text||!text.trim())return text;try{let body=new URLSearchParams({text,language:"en-US"});let r=await fetch("https://api.languagetool.org/v2/check",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body});if(!r.ok)return text;let d=await r.json(),matches=(d.matches||[]).filter(m=>Array.isArray(m.replacements)&&m.replacements.length&&typeof m.replacements[0].value==="string");matches.sort((a,c)=>c.offset-a.offset);let out=text;for(const m of matches)out=out.slice(0,m.offset)+m.replacements[0].value+out.slice(m.offset+m.length);return out}catch(e){return text}}
