async function googleBooksDescription(query,bt,at){let r=await fetch(`https://www.googleapis.com/books/v1/volumes?q=${query}&maxResults=10`),d=await r.json(),items=d.items||[],scored=items.map(x=>({x,score:titleAuthorScore((x.volumeInfo||{}).title,(x.volumeInfo||{}).authors,bt,at)})).sort((a,c)=>c.score-a.score),best=scored[0];if(best&&best.score>=50){let v=best.x.volumeInfo||{};if(typeof v.description==="string"&&v.description.trim())return v.description}return null}
