function libibUrl(){return localStorage.getItem("mpl-libib-url")||"https://www.libib.com/u/supernovammxv"}
function openLibib(){window.open(libibUrl(),"_blank","noopener,noreferrer")}
async function searchLibibFirst(){let q=$("coverSearch").value.trim();if(!q)return;$('coverResults').innerHTML='<div class="small">Checking Libib first…</div>';try{let u=libibUrl();let r=await fetch(u,{mode:"cors",cache:"no-store"});if(!r.ok)throw Error("Libib returned HTTP "+r.status);let text=await r.text();let isbn=[...new Set((text.match(/\b(?:97[89][ -]?)?\d(?:[ -]?\d){8,12}[0-9Xx]\b/g)||[]).map(x=>x.replace(/[ -]/g,"")))];let ql=q.toLowerCase().split(/\s+/).filter(Boolean);let hay=text.toLowerCase();let likely=ql.every(x=>hay.includes(x));if(likely&&isbn.length){let links=isbn.slice(0,6).map(i=>`<button type="button" class="cover-option" onclick="searchCoversWithQuery('isbn:${i}')"><span>Libib ISBN ${i}</span><span>Use this ISBN to find the matching cover</span></button>`).join("");$("coverResults").innerHTML=links;return}throw Error("No readable matching ISBN found") }catch(e){$("coverResults").innerHTML='<div class="small">Libib could not be read directly by this browser, so Open Library is being used instead. You can open Libib to check the exact edition.</div>';openLibib();await searchCovers()}}
async function searchCoversWithQuery(q){$("coverSearch").value=q;await searchCovers()}
async function searchCovers(){let q=$("coverSearch").value.trim();if(!q)return;$("coverResults").innerHTML='<div class="small">Searching for covers…</div>';try{let r=await fetch(`https://openlibrary.org/search.json?q=${encodeURIComponent(q)}&limit=12`),d=await r.json(),docs=(d.docs||[]).filter(x=>x.cover_i);if(!docs.length){$("coverResults").innerHTML='<div class="empty">No covers found. Try a different search.</div>';return}$("coverResults").innerHTML=docs.map(x=>{let u=`https://covers.openlibrary.org/b/id/${x.cover_i}-M.jpg`;return `<button type="button" class="cover-option" onclick="selectCover(${x.cover_i})"><img src="${u}" alt=""><span>${esc(x.title||"Unknown title")}${x.first_publish_year?` · ${x.first_publish_year}`:""}</span></button>`}).join("")}catch(e){$("coverResults").innerHTML='<div class="empty">Could not search Open Library.</div>'}}
async function selectCover(coverId){let b=books.find(x=>x.id===coverBookId);if(!b)return;b.coverId=coverId;b.coverUrl=`https://covers.openlibrary.org/b/id/${coverId}-M.jpg`;await cacheCover(b.coverUrl);persist();if($("bookDetailsDialog").open&&detailsBookId===coverBookId){renderDetailsCoverBox(b);await hydrateCoverImages()}$("coverDialog").close();toast("Cover saved")}
async function findMissingCovers(){let targets=books.filter(b=>!b.coverUrl&&!b.coverId),total=targets.length;if(!total){await hydrateCoverImages();$("coverProgress").textContent="All books already have covers. Nothing was searched again.";toast("No missing covers to search");return}let done=0,changed=0;$("coverProgress").textContent=`Finding covers… 0 of ${total}`;for(const b of targets){try{let found=await getCoverFromOpenLibrary(b);if(!found)found=await getCoverFromGoogleBooks(b);if(found){b.coverUrl=found.url;if(found.coverId)b.coverId=found.coverId;b.coverSource=found.source||"";await cacheCover(found.url);changed++;localStorage.setItem(STORAGE,JSON.stringify(books));renderAll();await hydrateCoverImages()}}catch(e){}done++;$("coverProgress").textContent=`Finding covers… ${done} of ${total} · ${changed} found`}$("coverProgress").textContent=`Finished. Found ${changed} new cover${changed===1?"":"s"}. Existing covers were not searched again.`;toast(changed?`Found ${changed} missing cover${changed===1?"":"s"}`:"No missing covers found")}
async function fixAllSynopsisGrammar(){let keys=Object.keys(detailsCache).filter(k=>detailsCache[k]&&detailsCache[k].description&&detailsCache[k].description.trim());let total=keys.length;if(!total){$("synopsisProgress").textContent="No saved synopsis text to check yet.";toast("No synopsis text to check");return}let done=0,changed=0;$("synopsisProgress").textContent=`Checking grammar & spelling… 0 of ${total}`;for(const k of keys){try{let orig=detailsCache[k].description,fixed=await cleanSynopsisText(orig);if(fixed&&fixed!==orig){detailsCache[k]={...detailsCache[k],description:fixed};changed++}}catch(e){}done++;$("synopsisProgress").textContent=`Checking grammar & spelling… ${done} of ${total} · ${changed} corrected`}persistDetailsCache();$("synopsisProgress").textContent=`Finished. Corrected ${changed} synopsis${changed===1?"":"es"}.`;if($("bookDetailsDialog").open&&detailsBookId!=null&&$("detailsSynopsisEdit").style.display==="none"){let b=books.find(x=>String(x.id)===String(detailsBookId));if(b){let key=bookKey(b);if(detailsCache[key])setSynopsisView(detailsCache[key].description)}}toast(changed?`Corrected ${changed} synopsis${changed===1?"":"es"}`:"No issues found")}
function bookDetailsClickHandler(e){let c=e.target.closest(".book-card");if(!c)return;if(e.target.closest("button,a,input,select,label"))return;openBookDetails(c.dataset.bookId)}$("libraryList").addEventListener("click",bookDetailsClickHandler);$("wishlistList").addEventListener("click",bookDetailsClickHandler);$("lookup").onclick=()=>lookupISBN($("isbn").value);$("isbn").addEventListener("keydown",e=>{if(e.key==="Enter"){e.preventDefault();lookupISBN(e.target.value)}});document.querySelectorAll(".nav").forEach(n=>n.onclick=()=>{document.querySelectorAll(".nav").forEach(x=>x.classList.remove("active"));n.classList.add("active");document.querySelectorAll(".view").forEach(v=>v.classList.remove("active"));$(n.dataset.view).classList.add("active");n.dataset.view==="scanner"?startCamera():stopCamera();if(n.dataset.view==="insights")stats()});$("search").oninput=renderLibrary;$("author").onchange=renderLibrary;$("genre").onchange=renderLibrary;$("series").onchange=renderLibrary;$("readState").onchange=renderLibrary;$("librarySort").onchange=renderLibrary;$("wishlistSort").onchange=renderWishlist;$("wishSearch").oninput=renderWishlist;$("wishAuthor").onchange=renderWishlist;$("wishGenre").onchange=renderWishlist;$("wishSeries").onchange=renderWishlist;
$("coverSearchBtn").onclick=searchCovers;$("libibSearchBtn").onclick=searchLibibFirst;$("openLibibBtn").onclick=openLibib;$("coverUpload").onchange=e=>{let f=e.target.files?.[0];if(!f||!coverBookId)return;let reader=new FileReader();reader.onload=()=>{let b=books.find(x=>x.id===coverBookId);if(!b)return;b.coverUrl=reader.result;b.coverId="";persist();if($("bookDetailsDialog").open&&detailsBookId===coverBookId)renderDetailsCoverBox(b);$("coverUpload").value="";$("coverDialog").close();toast("Uploaded cover saved")};reader.readAsDataURL(f)};$("coverSearch").addEventListener("keydown",e=>e.key==="Enter"&&searchCovers());$("closeCover").onclick=()=>$("coverDialog").close();$("closeBookDetails").onclick=()=>$("bookDetailsDialog").close();$("detailsCover").onclick=()=>{if(detailsBookId)chooseCover(detailsBookId)};$("detailsSynopsisEditBtn").onclick=()=>{$("detailsSynopsis").value=$("detailsSynopsisView").dataset.raw||"";$("detailsSynopsisView").style.display="none";$("detailsSynopsisEdit").style.display="";$("detailsSynopsis").focus()};$("detailsRelookup").onclick=async()=>{if(!detailsBookId)return;let b=books.find(x=>String(x.id)===String(detailsBookId));if(!b)return;let btn=$("detailsRelookup");btn.disabled=true;btn.textContent="Looking up…";try{let info=await fetchBookDetails(b);if(info.description){try{info.description=await cleanSynopsisText(info.description)}catch(e){}}$("detailsSynopsis").value=info.description||""}catch(e){}btn.disabled=false;btn.textContent="Look up again"};$("detailsFixGrammar").onclick=async()=>{let btn=$("detailsFixGrammar");btn.disabled=true;btn.textContent="Checking…";try{$("detailsSynopsis").value=await cleanSynopsisText($("detailsSynopsis").value)}catch(e){}btn.disabled=false;btn.textContent="Fix grammar & spelling"};$("detailsSaveSynopsis").onclick=()=>{if(!detailsBookId)return;let b=books.find(x=>String(x.id)===String(detailsBookId));if(!b)return;let key=bookKey(b),val=$("detailsSynopsis").value.trim();detailsCache[key]={description:val};persistDetailsCache();setSynopsisView(val);$("detailsSynopsisEdit").style.display="none";$("detailsSynopsisView").style.display="";toast("Synopsis saved")};async function setReadingStatus(statusValue){if(!detailsBookId)return;let b=books.find(x=>String(x.id)===String(detailsBookId));if(!b||String(b.format||"")==="Wishlist")return;b.readingStatus=statusValue;persist();openBookDetails(b.id);toast(statusValue==="Read"?"Marked as read": "Marked as DNF")}$("detailsReadBtn").onclick=()=>setReadingStatus("Read");$("detailsDnfBtn").onclick=()=>setReadingStatus("DNF");$("settingsBtn").onclick=()=>{$("webhook").value=localStorage.getItem(URLKEY)||DEFAULT_URL;$("libibUrl").value=libibUrl();applyTheme();$("syncState").textContent="Using your Google Apps Script endpoint.";$("settingsDialog").showModal()};$("darkMode").onchange=e=>{localStorage.setItem("mpl-dark-mode",e.target.checked?"1":"0");applyTheme()};$("findCovers").onclick=findMissingCovers;$("fixAllSynopsisGrammar").onclick=fixAllSynopsisGrammar;$("closeSettings").onclick=()=>$("settingsDialog").close();$("saveSettings").onclick=()=>{let u=$("webhook").value.trim();if(u)localStorage.setItem(URLKEY,u);else localStorage.removeItem(URLKEY);let lu=$("libibUrl").value.trim();if(lu)localStorage.setItem("mpl-libib-url",lu);else localStorage.removeItem("mpl-libib-url");$("settingsDialog").close();toast("Settings saved");pull()};$("syncNow").onclick=()=>pull();load();applyTheme();renderAll();pull(false);
